export class ConfigurationError extends Error {
  constructor(readonly variable: string, rule: string) {
    super("CONFIG_INVALID " + variable + ": " + rule);
    this.name = "ConfigurationError";
  }
}
const fail = (name: string, rule: string): never => { throw new ConfigurationError(name, rule); };
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
export const isLoopback = (hostname: string): boolean => ["localhost", "127.0.0.1", "[::1]", "::1"].includes(hostname);
function parseURL(name: string, raw: string, origin = false): URL {
  let url: URL;
  try { url = new URL(raw); } catch { return fail(name, "URL invalide"); }
  if (!["http:", "https:"].includes(url.protocol) || url.username || url.password || url.hash)
    fail(name, "URL HTTP(S) sans identifiants ni fragment requise");
  if (origin && url.origin !== raw) fail(name, "origine canonique sans chemin requise");
  return url;
}
function parseKey(name: string, raw: string): string {
  if (!/^[A-Za-z0-9+/]{43}=$/.test(raw) || Buffer.from(raw, "base64").length !== 32 || Buffer.from(raw, "base64").toString("base64") !== raw)
    fail(name, "cle de 32 octets encodee en base64 requise");
  return raw;
}
function parseList(name: string, raw: string): string[] {
  let value: unknown;
  try { value = JSON.parse(raw); } catch { return fail(name, "tableau JSON requis"); }
  if (!Array.isArray(value) || !value.every(x => typeof x === "string" && x.trim().length > 0 && !/[\r\n\0]/.test(x)))
    return fail(name, "tableau JSON de chaines non vides requis");
  return [...new Set(value)] as string[];
}
export interface ConfiguredLocale {code:string;label:string}
function parseLocales(raw:string,name="SITE_LOCALES_JSON",minimum=1):ConfiguredLocale[]{
  let input:unknown;try{input=JSON.parse(raw);}catch{return fail(name,"tableau de langues requis");}
  if(!Array.isArray(input)||input.length<minimum||input.length>8)return fail(name,"nombre de langues invalide (maximum huit)");
  const seen=new Set<string>(),reserved=new Set(["api","auth","media","site-logos","presentation-assets","preview","fonts","news","artworks","exhibitions","publications","expertise","contact","_next"]);
  for(const entry of input){
    if(!entry||typeof entry!=="object"||Array.isArray(entry)||Object.keys(entry).some(k=>k!=="code"&&k!=="label")||typeof entry.code!=="string"||entry.code.length>35||!/^[a-z]{2,3}(?:-[a-z0-9]{2,8})*$/.test(entry.code)||reserved.has(entry.code)||seen.has(entry.code)||typeof entry.label!=="string"||!entry.label.trim()||Array.from(entry.label).length>80||/[\r\n\0]/.test(entry.label))return fail(name,"langue invalide, reservee ou dupliquee");
    seen.add(entry.code);
  }
  return input as ConfiguredLocale[];
}
export function configuredLocalePolicy(config:Config):{defaultLocale:string;locales:ConfiguredLocale[]}{
  const locales=parseLocales(stringValue(config,"SITE_LOCALES_JSON")),defaultLocale=stringValue(config,"SITE_DEFAULT_LOCALE");
  if(config.ARTLOGIC_DESCRIPTION_SOURCE_LOCALE&&(String(config.ARTLOGIC_DESCRIPTION_SOURCE_LOCALE).length>35||!/^[a-z]{2,3}(?:-[a-z0-9]{2,8})*$/.test(String(config.ARTLOGIC_DESCRIPTION_SOURCE_LOCALE))))fail("ARTLOGIC_DESCRIPTION_SOURCE_LOCALE","langue source invalide");
  if(!locales.some(locale=>locale.code===defaultLocale))fail("SITE_DEFAULT_LOCALE","doit appartenir aux langues configurees");
  return {defaultLocale,locales};
}
export function configuredEditorialLocalePolicy(config:Config){
  const {defaultLocale,locales:activeLocales}=configuredLocalePolicy(config);
  const preparingLocales=parseLocales(String(config.EDITORIAL_PREPARING_LOCALES_JSON??"[]"),"EDITORIAL_PREPARING_LOCALES_JSON",0);
  if(activeLocales.length+preparingLocales.length>8||preparingLocales.some(locale=>activeLocales.some(active=>active.code===locale.code)))fail("EDITORIAL_PREPARING_LOCALES_JSON","langues actives et preparatoires distinctes, huit au total maximum");
  return {defaultLocale,activeLocales,preparingLocales};
}
export function canonicalJson(value:unknown):string{
  if(Array.isArray(value))return "["+value.map(canonicalJson).join(",")+"]";
  if(value!==null&&typeof value==="object")return "{"+Object.keys(value).sort().map(key=>JSON.stringify(key)+":"+canonicalJson((value as Record<string,unknown>)[key])).join(",")+"}";
  const encoded=JSON.stringify(value);if(encoded===undefined)throw new Error("Value is not canonical JSON");return encoded;
}
function parse(name: string, raw: string, rule: Rule): ConfigValue {
  switch (rule.kind) {
    case "mailbox":
      if(raw.length>254||!/^[^\s<>@,;]+@[^\s<>@,;]+\.[^\s<>@,;]+$/.test(raw)||/[\r\n\0]/.test(raw))fail(name,"adresse e-mail simple requise");
      return raw;
    case "smtphost":
      if(!raw||raw.length>253||/[\s/\\:@?#\0]/.test(raw)&&!isIP(raw))fail(name,"nom de serveur SMTP ou IP requis");
      return raw;
    case "headername":
      if(!/^x-[a-z0-9-]{1,60}$/.test(raw)||/^(x-forwarded-|x-real-ip$|x-contact-ingress-key$)/.test(raw))fail(name,"en-tete ingress dedie requis");
      return raw;
    case "retrydelays": {
      let list:unknown;try{list=JSON.parse(raw);}catch{return fail(name,"tableau de delais requis");}
      if(!Array.isArray(list)||!list.every(n=>Number.isSafeInteger(n)&&n>=1&&n<=86400))fail(name,"delais entiers entre 1 et 86400 requis");
      return JSON.stringify(list);
    }
    case "profile":
      if(!/^[a-z][a-z0-9-]{0,63}$/.test(raw))fail(name,"identifiant de profil invalide");
      return raw;
    case "localpath":
      if(!raw.trim()||raw!==raw.trim()||raw.length>4096||/[\r\n\0]/.test(raw)||/^[a-z][a-z0-9+.-]*:/i.test(raw))fail(name,"chemin local requis, jamais une URL");
      return raw;
    case "locales": return JSON.stringify(parseLocales(raw));
    case "preparinglocales": return JSON.stringify(parseLocales(raw,name,0));
    case "timezone":
      if(!raw.trim()||raw!==raw.trim()||raw.length>80||/^[+-]/.test(raw))fail(name,"fuseau IANA requis");
      try{new Intl.DateTimeFormat("en",{timeZone:raw}).format();}catch{return fail(name,"fuseau IANA invalide");}
      return raw;
    case "number": {
      const n = Number(raw);
      if (!/^[0-9]+$/.test(raw) || !Number.isSafeInteger(n) || n < (rule.min ?? 0) || n > (rule.max ?? Number.MAX_SAFE_INTEGER))
        fail(name, "entier hors bornes");
      return n;
    }
    case "enum":
      if (!rule.values?.includes(raw)) fail(name, "valeur non autorisee");
      return raw;
    case "uuid":
      if (!uuid.test(raw)) fail(name, "UUID requis");
      return raw;
    case "key": return parseKey(name, raw);
    case "keymap": {
      let value: unknown;
      try { value = JSON.parse(raw); } catch { return fail(name, "objet JSON requis"); }
      if (!value || typeof value !== "object" || Array.isArray(value)) return fail(name, "objet JSON requis");
      for (const [id, key] of Object.entries(value)) {
        if (!/^[A-Za-z0-9_-]{1,64}$/.test(id) || typeof key !== "string") fail(name, "identifiant ou cle invalide");
        parseKey(name, key as string);
      }
      return value as Record<string, string>;
    }
    case "token":
      if (Buffer.byteLength(raw, "utf8") < 32 || /[\r\n\0]/.test(raw)) fail(name, "secret d'au moins 32 octets requis");
      return raw;
    case "origin":
    case "url": parseURL(name, raw, rule.kind === "origin"); return raw;
    case "database": {
      let url: URL;
      try { url = new URL(raw); } catch { return fail(name, "URL PostgreSQL requise"); }
      if (!["postgres:", "postgresql:"].includes(url.protocol) || !url.hostname || !url.username || !url.password || url.hash)
        fail(name, "URL PostgreSQL complete requise");
      const sslMode = url.searchParams.get("sslmode");
      if (sslMode && !["verify-full", "disable"].includes(sslMode)) fail(name, "verification TLS complete requise");
      if (!isLoopback(url.hostname) && sslMode === "disable") fail(name, "TLS obligatoire hors loopback");
      if (["ssl", "sslcert", "sslkey", "sslrootcert"].some(k => url.searchParams.has(k)))
        fail(name, "configurer TLS via PG_SSL_CA");
      return raw;
    }
    case "cidrs":
    case "origins":
    case "hosts":
    case "list": {
      const list = parseList(name, raw);
      if (rule.required && rule.kind !== "list" && list.length === 0) fail(name, "liste non vide requise");
      if (rule.kind === "origins") list.forEach(x => parseURL(name, x, true));
      if (rule.kind === "cidrs") {
        for (const cidr of list) {
          const [address,prefix,...extra]=cidr.split("/");
          const version=isIP(address??""); const bits=Number(prefix);
          if(extra.length || !version || !/^[0-9]+$/.test(prefix??"") || bits<1 || bits>(version===4?32:128)) fail(name,"CIDR IP explicite requis, sans plage globale");
        }
      }
      if (rule.kind === "hosts") {
        for (const host of list) {
          let valid = false;
          try { valid = !host.includes("*") && !/[\s/:?#@]/.test(host) && new URL("https://" + host).hostname === host; } catch { valid = false; }
          if (!valid) fail(name, "noms d'hotes exacts requis");
        }
      }
      return list;
    }
    default:
      if (raw.includes("\0")) fail(name, "caractere interdit");
      return raw;
  }
}
export function stringValue(config: Config, name: string): string {
  const v = config[name];
  if (typeof v !== "string") return fail(name, "chaine requise pour ce processus");
  return v;
}
export function numberValue(config: Config, name: string): number {
  const v = config[name];
  if (typeof v !== "number") return fail(name, "nombre requis pour ce processus");
  return v;
}
export function listValue(config: Config, name: string): string[] {
  const v = config[name];
  if (!Array.isArray(v)) return fail(name, "liste requise pour ce processus");
  return v;
}
export function readConfig(role: Scope, env: Record<string, string | undefined> = process.env): Config {
  const result: Record<string, ConfigValue | undefined> & { role: Scope } = { role };
  for (const [name, rule] of Object.entries(variables)) {
    if (!rule.scopes.includes(role)) continue;
    const raw = env[name] === "" ? undefined : env[name];
    const input = raw ?? rule.default;
    if (input === undefined) {
      if (rule.required&&!rule.optionalScopes?.includes(role)) fail(name, "variable obligatoire");
      continue;
    }
    result[name] = parse(name, input, rule);
  }
  const config = result as Config;
  if(config.MCP_ENABLED==="true"&&(role==="A"||role==="W")){
    for(const name of ["MCP_RESOURCE_URL","MCP_CLIENT_ID","CRM_SITE_DIRECTORY_URL","CRM_SITE_DIRECTORY_CLIENT_ID","CRM_SITE_DIRECTORY_KEY_ID","CRM_SITE_DIRECTORY_PRIVATE_KEY",...(role==="A"?["MCP_OAUTH_ISSUER_URL","MCP_CLIENT_SECRET_HASH","MCP_CLIENT_REDIRECT_URIS_JSON"]:["SSO_ISSUER","SSO_SUPABASE_URL","ADMIN_ORIGIN"])])if(!config[name])fail(name,"requis pour la delegation MCP active");
    const scopes=listValue(config,"MCP_ALLOWED_SCOPES_JSON"),knownScopes=["site.read","site.draft","site.publish","site.sync","site.connector.manage"];
    if(scopes.length<1||scopes.length>5||new Set(scopes).size!==scopes.length||scopes.some(s=>!knownScopes.includes(s))||!scopes.includes("site.read")||scopes.includes("site.publish")&&!scopes.includes("site.draft"))fail("MCP_ALLOWED_SCOPES_JSON","scopes explicites coherents incluant site.read requis");
    const resource=new URL(stringValue(config,"MCP_RESOURCE_URL"));
    if(resource.protocol!=="https:"||resource.pathname!=="/mcp"||resource.search||resource.hash||resource.username||resource.password||resource.hostname.includes("*"))fail("MCP_RESOURCE_URL","ressource HTTPS exacte /mcp requise");
    const client=stringValue(config,"MCP_CLIENT_ID");if(!client.trim()||client!==client.trim()||client.length>200||/[\r\n\0]/.test(client))fail("MCP_CLIENT_ID","client enregistre borne requis");
    if(numberValue(config,"MCP_REFRESH_IDLE_SECONDS")>numberValue(config,"MCP_REFRESH_ABSOLUTE_SECONDS"))fail("MCP_REFRESH_IDLE_SECONDS","ne peut depasser la duree absolue");
    if(role==="A"){
      if(stringValue(config,"MCP_OAUTH_ISSUER_URL")!==resource.origin+"/oauth/mcp")fail("MCP_OAUTH_ISSUER_URL","issuer exact du backend /oauth/mcp requis");
      if(!/^[a-f0-9]{64}$/.test(stringValue(config,"MCP_CLIENT_SECRET_HASH")))fail("MCP_CLIENT_SECRET_HASH","SHA-256 hex requis");
      const redirects=listValue(config,"MCP_CLIENT_REDIRECT_URIS_JSON");if(!redirects.length||redirects.length>8||new Set(redirects).size!==redirects.length)fail("MCP_CLIENT_REDIRECT_URIS_JSON","un a huit callbacks exacts uniques requis");
      for(const raw of redirects){let u:URL;try{u=new URL(raw);}catch{return fail("MCP_CLIENT_REDIRECT_URIS_JSON","callback invalide");}if(u.protocol!=="https:"||u.username||u.password||u.hash||u.hostname.includes("*")||raw.length>2048)fail("MCP_CLIENT_REDIRECT_URIS_JSON","callback HTTPS exact sans wildcard ou fragment requis");}
    }
  }
  if(role==="A"){

    if(config.MEDIA_S3_ENDPOINT){const url=parseURL("MEDIA_S3_ENDPOINT",stringValue(config,"MEDIA_S3_ENDPOINT"));if(url.search||url.hostname.includes("*")||url.protocol!=="https:"&&!(config.DATA_MODE==="mock"&&isLoopback(url.hostname)))fail("MEDIA_S3_ENDPOINT","endpoint HTTPS exact requis");}
  }
  if(role==="F"){
    const siteOrigins=listValue(config,"SITE_ALLOWED_ORIGINS_JSON");
    if(siteOrigins.length>16)fail("SITE_ALLOWED_ORIGINS_JSON","seize origines maximum");
    for(const origin of siteOrigins){const url=parseURL("SITE_ALLOWED_ORIGINS_JSON",origin,true);if(url.hostname.includes("*")||url.protocol!=="https:"&&!(config.DATA_MODE==="mock"&&isLoopback(url.hostname)))fail("SITE_ALLOWED_ORIGINS_JSON","origine HTTPS exacte requise");}
    const origins=listValue(config,"PUBLIC_MEDIA_DELIVERY_ORIGINS_JSON");
    if(config.PUBLIC_IMAGE_RESPONSIVE_ENABLED==="true"&&config.PUBLIC_MEDIA_DIRECT_ENABLED!=="true")fail("PUBLIC_IMAGE_RESPONSIVE_ENABLED","diffusion directe requise");
    if(config.PUBLIC_MEDIA_DIRECT_ENABLED==="true"&&!origins.length)fail("PUBLIC_MEDIA_DELIVERY_ORIGINS_JSON","origine requise en direct");
    for(const origin of origins){const url=parseURL("PUBLIC_MEDIA_DELIVERY_ORIGINS_JSON",origin,true);if(url.hostname.includes("*")||url.protocol!=="https:"&&!(config.DATA_MODE==="mock"&&isLoopback(url.hostname)))fail("PUBLIC_MEDIA_DELIVERY_ORIGINS_JSON","origine HTTPS exacte requise");}
    if(numberValue(config,"PUBLIC_MEDIA_LOAD_TIMEOUT_MS")<numberValue(config,"PUBLIC_PAGE_REQUEST_TIMEOUT_MS")+5000)fail("PUBLIC_MEDIA_LOAD_TIMEOUT_MS","doit couvrir la deadline publique plus 5000 ms");
  }

  if(config.PREVIEW_SERVICE_KEY&&config.PREVIEW_SERVICE_KEY===env.BFF_SERVICE_KEY)
    fail("PREVIEW_SERVICE_KEY","doit etre distinct de BFF_SERVICE_KEY");
  if(role!=="X")configuredLocalePolicy(config);
  if(["A","W","M"].includes(role)){
    configuredEditorialLocalePolicy(config);
    if(config.EDITORIAL_ENABLED==="true"&&!config.EDITORIAL_TIME_ZONE)fail("EDITORIAL_TIME_ZONE","variable obligatoire quand le module editorial est actif");
  }
  if(role==="A"||role==="W"){
    if(config.PG_CONNECTION_BUDGET!==undefined){
      if(config.PG_API_INSTANCE_LIMIT===undefined)fail("PG_API_INSTANCE_LIMIT","plafond de deploiement requis pour le budget");
      const expected=numberValue(config,"PG_API_POOL_BUDGET")*numberValue(config,"PG_API_INSTANCE_LIMIT")+numberValue(config,"PG_WORKER_POOL_BUDGET")*numberValue(config,"PG_WORKER_INSTANCE_LIMIT")+numberValue(config,"PG_CONNECTION_RESERVE");
      if(expected>numberValue(config,"PG_CONNECTION_BUDGET"))fail("PG_CONNECTION_BUDGET","budget agrege insuffisant");
      if(numberValue(config,"PG_POOL_MAX")>numberValue(config,role==="A"?"PG_API_POOL_BUDGET":"PG_WORKER_POOL_BUDGET"))fail("PG_POOL_MAX","depasse le budget du role");
    }
    const lease=numberValue(config,"PRESENTATION_FINALIZE_LEASE_SECONDS");
    if(numberValue(config,"PRESENTATION_FINALIZE_RENEW_SECONDS")>=lease)fail("PRESENTATION_FINALIZE_RENEW_SECONDS","doit etre inferieur a la lease");
    for(const name of ["PRESENTATION_VIDEO_FINALIZE_SECONDS","PRESENTATION_OTHER_FINALIZE_SECONDS"])if(numberValue(config,name)<lease)fail(name,"doit couvrir la lease");
    if(role==="W"&&numberValue(config,"PRESENTATION_FINALIZE_RECONCILE_SECONDS")>lease)fail("PRESENTATION_FINALIZE_RECONCILE_SECONDS","doit etre inferieur ou egal a la lease");
    if(role==="A"){
      if(numberValue(config,"PRESENTATION_ATTEMPT_ADMIN_ACTIVE_LIMIT")>numberValue(config,"PRESENTATION_ATTEMPT_SITE_ACTIVE_LIMIT"))fail("PRESENTATION_ATTEMPT_ADMIN_ACTIVE_LIMIT","doit etre inferieur ou egal au plafond site");
      if(numberValue(config,"PRESENTATION_ATTEMPT_ADMIN_HOURLY_LIMIT")>numberValue(config,"PRESENTATION_ATTEMPT_SITE_HOURLY_LIMIT"))fail("PRESENTATION_ATTEMPT_ADMIN_HOURLY_LIMIT","doit etre inferieur ou egal au plafond site");
    }
  }
  const mode = stringValue(config, "DATA_MODE");
  const deployment = stringValue(config, "DEPLOYMENT_ENV");
  const notificationMode=config.FORMS_NOTIFICATION_MODE??mode;
  if(config.FORMS_CONTACT_CUTOVER==="true"&&config.FORMS_ENABLED!=="true")fail("FORMS_CONTACT_CUTOVER","module Forms requis");
  if(config.FORMS_NOTIFICATIONS_ENABLED==="true"&&config.FORMS_ENABLED!=="true")fail("FORMS_NOTIFICATIONS_ENABLED","module Forms requis");
  if(config.FORMS_ENABLED==="true"&&["A","W","M"].includes(role)){
    const bucket=config.FORM_ATTACHMENTS_BUCKET;
    if(!config.FORM_EXPORTS_BUCKET)result.FORM_EXPORTS_BUCKET="forms-exports-"+stringValue(config,"SITE_ID");
    if(typeof config.FORM_EXPORTS_BUCKET!=="string"||! /^[a-z0-9][a-z0-9-]{2,62}$/.test(config.FORM_EXPORTS_BUCKET)||[config.MEDIA_BUCKET,bucket].includes(config.FORM_EXPORTS_BUCKET))fail("FORM_EXPORTS_BUCKET","bucket prive distinct pour les exports requis");
    if(typeof bucket!=="string"||! /^[a-z0-9][a-z0-9-]{2,62}$/.test(bucket)||bucket===config.MEDIA_BUCKET)fail("FORM_ATTACHMENTS_BUCKET","bucket prive distinct des medias publics requis");
  }
  if(config.FORMS_NOTIFICATIONS_ENABLED==="true"){
    if(numberValue(config,"FORM_NOTIFICATION_ENCODED_MAX_BYTES")<8192)fail("FORM_NOTIFICATION_ENCODED_MAX_BYTES","minimum 8192 octets pour le corps et les en-tetes");
    const required=["CRM_SITE_DIRECTORY_URL","CRM_SITE_DIRECTORY_CLIENT_ID","CRM_SITE_DIRECTORY_KEY_ID","CRM_SITE_DIRECTORY_PRIVATE_KEY","RESEND_FROM_EMAIL",...(role==="A"?["RESEND_WEBHOOK_SECRET"]:role==="W"?["RESEND_API_KEY","SSO_ISSUER","SSO_SUPABASE_URL","ADMIN_ALLOWED_SUBJECTS","ADMIN_ORIGIN"]:["RESEND_API_KEY","RESEND_WEBHOOK_SECRET"])];
    for(const name of required)if(!config[name])fail(name,"variable obligatoire si notifications Forms actives");
  }
  if(config.FORMS_NOTIFICATIONS_ENABLED==="true"&&notificationMode==="real"&&new URL(String(config.CRM_SITE_DIRECTORY_URL)).protocol!=="https:")fail("CRM_SITE_DIRECTORY_URL","HTTPS requis pour les notifications reelles");
  if(config.CRM_SITE_DIRECTORY_PRIVATE_KEY){
    try{
      const jwk=JSON.parse(String(config.CRM_SITE_DIRECTORY_PRIVATE_KEY)) as Record<string,unknown>;
      if(jwk.kty!=="OKP"||jwk.crv!=="Ed25519"||![jwk.x,jwk.d].every(v=>typeof v==="string"&&/^[A-Za-z0-9_-]{43}$/.test(v)))throw new Error();
    }catch{fail("CRM_SITE_DIRECTORY_PRIVATE_KEY","JWK prive Ed25519 JSON monoligne requis");}
  }
  if(config.FORMS_NOTIFICATIONS_ENABLED==="true"&&notificationMode==="mock"){
    if(!isLoopback(new URL(String(config.CRM_SITE_DIRECTORY_URL)).hostname))fail("CRM_SITE_DIRECTORY_URL","annuaire mock local requis");
    if(config.RESEND_API_BASE_URL&&!isLoopback(new URL(String(config.RESEND_API_BASE_URL)).hostname))fail("RESEND_API_BASE_URL","livraison mock locale requise");
    if(!String(config.RESEND_FROM_EMAIL).endsWith(".test"))fail("RESEND_FROM_EMAIL","adresse synthetique .test requise en mock");
  }
  if(notificationMode==="real"&&config.RESEND_API_BASE_URL&&String(config.RESEND_API_BASE_URL)!=="https://api.resend.com")fail("RESEND_API_BASE_URL","origine Resend officielle requise en reel");
  if(config.CONTACT_SERVICE_KEY&&[env.BFF_SERVICE_KEY,env.PREVIEW_SERVICE_KEY,env.CONTACT_INGRESS_KEY].includes(String(config.CONTACT_SERVICE_KEY)))fail("CONTACT_SERVICE_KEY","doit etre distinct des autres cles de service");
  if(role==="F"&&mode==="real"){
    for(const name of ["CONTACT_TRUSTED_INGRESS_HEADER","CONTACT_INGRESS_KEY"])if(!config[name])fail(name,"variable obligatoire en mode real, meme contact desactive");
    if([env.CONTACT_SERVICE_KEY,env.PREVIEW_SERVICE_KEY,env.BFF_SERVICE_KEY].includes(String(config.CONTACT_INGRESS_KEY)))fail("CONTACT_INGRESS_KEY","cle ingress distincte requise");
  }
  if(["A","W"].includes(role)){
    const delays=JSON.parse(stringValue(config,"CONTACT_RETRY_DELAYS_SECONDS_JSON")) as number[];
    if(delays.length!==numberValue(config,"CONTACT_AUTOMATIC_MAX_ATTEMPTS")-1||delays.reduce((a,b)=>a+b,0)>=numberValue(config,"CONTACT_AUTOMATIC_WINDOW_SECONDS"))fail("CONTACT_RETRY_DELAYS_SECONDS_JSON","nombre de delais ou fenetre de reprise incoherent");
    if(config.CONTACT_ENABLED==="true"){
      for(const name of ["CONTACT_TO_EMAIL","CONTACT_FROM_EMAIL","CONTACT_SMTP_HOST","CONTACT_SMTP_PORT","CONTACT_SMTP_TLS_MODE",...(role==="A"?["CONTACT_PRIVACY_URL"]:[])])if(!config[name])fail(name,"variable obligatoire si contact active");
      const host=String(config.CONTACT_SMTP_HOST),tls=config.CONTACT_SMTP_TLS_MODE;
      if(mode==="mock"){
        if(!isLoopback(host)||tls!=="plain")fail("CONTACT_SMTP_HOST","SMTP mock limite au loopback sans livraison externe");
        for(const name of ["CONTACT_TO_EMAIL","CONTACT_FROM_EMAIL"])if(!String(config[name]).toLowerCase().endsWith(".test"))fail(name,"adresse synthetique .test requise en mock");
      }else{
        if(isLoopback(host)||tls==="plain"||![465,587].includes(Number(config.CONTACT_SMTP_PORT)))fail("CONTACT_SMTP_TLS_MODE","SMTP TLS verifie sur 465 ou 587 requis en reel");
        for(const name of ["CONTACT_SMTP_USER","CONTACT_SMTP_PASSWORD"])if(!config[name]||/[\r\n\0]/.test(String(config[name])))fail(name,"identifiant SMTP requis en reel");
      }
    }
  }

  if (deployment === "production") {
    if (mode !== "real") fail("DATA_MODE", "real obligatoire en production");
    if (config.NODE_ENV !== "production") fail("NODE_ENV", "production obligatoire au deploiement");
  }
  if (role === "X" && (mode !== "mock" || deployment === "production")) fail("DATA_MODE", "simulateur reserve a local/test mock");
  if (role === "X" && env.PORT === undefined) result.PORT = 4010;
  if (role === "A" && config.BACKEND_PUBLIC_ORIGIN === undefined) {
    if (deployment === "production") fail("BACKEND_PUBLIC_ORIGIN", "variable obligatoire en production");
    result.BACKEND_PUBLIC_ORIGIN = "http://127.0.0.1:4000";
  }
  for (const [name, rule] of Object.entries(variables)) {
    const value = config[name];
    if (!value || !["url", "origin", "origins", "database"].includes(rule.kind)) continue;
    const urls = Array.isArray(value) ? value : [value as string];
    for (const raw of urls) {
      const url = new URL(raw);
      if (mode === "real" && (["http:", "https:"].includes(url.protocol) && url.protocol !== "https:"))
        fail(name, "HTTPS obligatoire en mode real");
      if (mode === "real" && isLoopback(url.hostname)) fail(name, "loopback interdit en mode real");
      if (mode === "real" && rule.kind === "database" && url.searchParams.get("sslmode") === "disable")
        fail(name, "TLS obligatoire en mode real");
      if (mode === "mock" && ["SITE_ORIGIN", "ADMIN_ORIGIN"].includes(name) && url.protocol === "http:" && !isLoopback(url.hostname))
        fail(name, "HTTP navigateur reserve au loopback en mock");
    }
  }
  if (["A", "W"].includes(role) && mode === "mock") {
    const origins = listValue(config, "MOCK_ALLOWED_ORIGINS");
    for (const name of role === "A" ? ["SSO_ISSUER", "SSO_SUPABASE_URL", "CATALOG_SUPABASE_URL"] : ["ARTLOGIC_ARTWORKS_URL", "CATALOG_SUPABASE_URL"]) {
      if (!origins.includes(new URL(stringValue(config, name)).origin)) fail("MOCK_ALLOWED_ORIGINS", "origine de dependance absente");
    }
  }
  if (role === "W") {
    const interval = numberValue(config, "SYNC_PAGE_INTERVAL_MS"), cooldown = numberValue(config, "SYNC_PAGE_COOLDOWN_MS");
    if (mode === "real" && interval < 1000) fail("SYNC_PAGE_INTERVAL_MS", "minimum fournisseur 1000 ms");
    if (mode === "real" && cooldown < 300000) fail("SYNC_PAGE_COOLDOWN_MS", "minimum fournisseur 300000 ms");
    if (numberValue(config, "SYNC_LEASE_SECONDS") < 3 * numberValue(config, "SYNC_HEARTBEAT_SECONDS"))
      fail("SYNC_LEASE_SECONDS", "au moins trois heartbeats");
    const deadline = numberValue(config, "SYNC_RUN_TIMEOUT_SECONDS");
    for (const name of ["SYNC_PAGE_TIMEOUT_MS", "MEDIA_TIMEOUT_MS"])
      if (numberValue(config, name) >= deadline * 1000) fail(name, "doit etre inferieur a la deadline");
    if (!listValue(config, "ARTLOGIC_FEED_ALLOWED_ORIGINS").includes(new URL(stringValue(config, "ARTLOGIC_ARTWORKS_URL")).origin))
      fail("ARTLOGIC_FEED_ALLOWED_ORIGINS", "origine initiale absente");
    if (Boolean(config.SOURCE_AUTH_HEADER_NAME) !== Boolean(config.SOURCE_AUTH_HEADER_VALUE))
      fail("SOURCE_AUTH_HEADER_NAME", "nom et valeur doivent etre fournis ensemble");
    const name = config.SOURCE_AUTH_HEADER_NAME;
    if (typeof name === "string" && (!/^[!#$%&'*+.^_|~0-9A-Za-z-]+$/.test(name) || /^(host|cookie|connection|content-length|transfer-encoding|proxy-.*|x-forwarded-.*)$/i.test(name)))
      fail("SOURCE_AUTH_HEADER_NAME", "en-tete non autorise");
    if (typeof config.SOURCE_AUTH_HEADER_VALUE === "string" && /[\r\n\0]/.test(config.SOURCE_AUTH_HEADER_VALUE))
      fail("SOURCE_AUTH_HEADER_VALUE", "caractere interdit");
  }
  if (["A", "W"].includes(role) && numberValue(config, "SYNC_LEASE_SECONDS") >= numberValue(config, "SYNC_RUN_TIMEOUT_SECONDS"))
    fail("SYNC_LEASE_SECONDS", "doit etre inferieure a la deadline");
  if (role === "A") {
    if ((numberValue(config,"TRUST_PROXY_HOPS")>0) !== (listValue(config,"TRUST_PROXY_CIDRS").length>0))
      fail("TRUST_PROXY_CIDRS","renseigner les proxies controles avec un nombre de sauts positif");
    if (numberValue(config, "SESSION_IDLE_SECONDS") > numberValue(config, "SESSION_ABSOLUTE_SECONDS"))
      fail("SESSION_IDLE_SECONDS", "ne peut pas depasser la duree absolue");
    if (config.SSO_REDIRECT_URI !== stringValue(config, "ADMIN_ORIGIN") + "/auth/callback")
      fail("SSO_REDIRECT_URI", "doit correspondre exactement au callback de ADMIN_ORIGIN");
  }
  if (typeof config.DATA_ENCRYPTION_KEY_ID === "string" && !/^[A-Za-z0-9_-]{1,64}$/.test(config.DATA_ENCRYPTION_KEY_ID))
    fail("DATA_ENCRYPTION_KEY_ID", "identifiant de cle invalide");
  const previousKeys = config.DATA_ENCRYPTION_PREVIOUS_KEYS_JSON;
  if (config.DATA_ENCRYPTION_KEY_ID && previousKeys && typeof previousKeys === "object" && Object.hasOwn(previousKeys, stringValue(config, "DATA_ENCRYPTION_KEY_ID")))
    fail("DATA_ENCRYPTION_PREVIOUS_KEYS_JSON", "ne pas redeclarer la cle courante");
  const previousContactKeys=config.CONTACT_NETWORK_HMAC_PREVIOUS_KEYS_JSON;
  if(config.CONTACT_NETWORK_HMAC_KEY_ID&&previousContactKeys&&typeof previousContactKeys==="object"&&Object.hasOwn(previousContactKeys,stringValue(config,"CONTACT_NETWORK_HMAC_KEY_ID")))fail("CONTACT_NETWORK_HMAC_PREVIOUS_KEYS_JSON","ne pas redeclarer la cle courante");
  return Object.freeze(result);
}

export const loadConfig = () => readConfig("B");
